import{_ as o,l as i,o as e,c as s,v as t,p as l,x as r,d as c,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"行缓冲与 bank 冲突","description":"","frontmatter":{"title":"行缓冲与 bank 冲突","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/row-buffer-bank-conflict.md","filePath":"cs/row-buffer-bank-conflict.md","lastUpdated":1789023840000}'),E={name:"cs/row-buffer-bank-conflict.md"};function h(p,a,C,_,b,f){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="行缓冲与-bank-冲突" tabindex="-1">行缓冲与 bank 冲突 <a class="header-anchor" href="#行缓冲与-bank-冲突" aria-label="Permalink to &quot;行缓冲与 bank 冲突&quot;">​</a></h1><div class="epigraph"><p>灵敏放大器里躺着当前打开的那一行：列命中只需 $t_{CAS}$；换行则要预充电再激活，同一 bank 上的冲突把延迟拉成好几倍。</p><footer>—— 据 JEDEC DDR SDRAM 时序；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/dram-organization">上一课</a>钉了层次。体系结构课<a href="/cs/dram-timing">DRAM 时序</a>已写 \\(t_{RCD}\\)/\\(t_{CAS}\\)/\\(t_{RP}\\)。缺口是把<strong>行缓冲</strong>说成硬件状态：命中、缺失、冲突，以及为何多 bank 能掩盖冲突——否则后课调度没有优化目标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ACT 把一行读进该 bank 的行缓冲（灵敏放大器）。随后 READ/WRITE 走列地址，延迟 \\(t_{CCD}\\)/\\(t_{CAS}\\) 一类。访问另一行：先 PRE（\\(t_{RP}\\)）再 ACT（\\(t_{RCD}\\)）。同一 bank 连续不同行 = bank 冲突。不同 bank 可交错命令。缺口不是新的组织名词，而是这三种访问的延迟差：行命中 ≪ 行空闲（已预充）≪ 行冲突。</p><p>页模式、打开页 vs 关闭页策略：保持行开以盼空间局部性，或立刻 PRE 以降低冲突代价。后课 FR-FCFS 偏向打开页。</p><h3 id="行缓冲不是-cpu-cache" tabindex="-1">行缓冲不是 CPU cache <a class="header-anchor" href="#行缓冲不是-cpu-cache" aria-label="Permalink to &quot;行缓冲不是 CPU cache&quot;">​</a></h3><p>它是 DRAM 内部的模拟+数字状态，不参与缓存一致性协议，不按缓存行标签查找。CPU 的 L1 命中根本不看见它。把 row buffer 当 L4，目录协议会画错。</p><p><span class="marginnote">JEDEC 用 Activate/Precharge/Read/Write 定义状态机。CA:AQA 用行命中率解释有效延迟。本课不把 RowHammer 扰动写成主体，点名存在即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制器为每 bank 记 <code>open_row</code> 或 <code>closed</code>。请求到达：同行则列命令；他行则 PRE+ACT+列；关闭则 ACT+列。bank 组规则限制同组连续 ACT。统计：行命中率随地址映射与程序步长变，下一课映射会改命中。</p>',11)),(e(),l(A,null,{default:r(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%88%97%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20HIT%5B%22%E5%90%8C%E8%A1%8C%EF%BC%9A%E5%8F%AA%20CAS%22%5D%0A%20%20REQ%20--%3E%20MISS%5B%22%E5%85%B3%E9%97%AD%EF%BC%9AACT%2BCAS%22%5D%0A%20%20REQ%20--%3E%20CONF%5B%22%E4%BB%96%E8%A1%8C%EF%BC%9APRE%2BACT%2BCAS%22%5D%0A%20%20CONF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%91%BD%E4%BB%A4%E4%B8%8E%E6%97%B6%E5%BA%8F%E5%8F%82%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>多通道：冲突是每通道本地的；全局带宽仍可叠加。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地址交织把连续 cache 行洒到不同 bank，降低冲突、也可能降低行命中——折中在映射课。FR-FCFS 先服务能行命中的请求，可能饿死。HBM 银行更多，冲突模型同形。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列齐某代全部时序符号，不把内存控制器 RTL 写完。不进入加密侧信道（行缓冲时序泄漏）。不写光刻套准对电容的影响。</p><p>后课默认：延迟三档由行缓冲状态决定；bank 冲突是同一 bank 换行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行缓冲保存打开行；命中、空闲、冲突延迟差一个数量级。</li><li>多 bank 交错掩盖冲突；策略在打开/关闭页之间选。</li><li>不是 CPU cache。</li><li>出处：JEDEC DDR 时序；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const B=o(E,[["render",h]]);export{u as __pageData,B as default};
